-- Historical import is a reviewed factual record; it does not alter booking status.
CREATE TABLE booking_fulfilment_import_batches(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),created_by TEXT NOT NULL REFERENCES "user"(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE booking_fulfilment_import_refs(source_ref TEXT PRIMARY KEY NOT NULL,fulfilment_id TEXT NOT NULL UNIQUE,batch_id TEXT NOT NULL REFERENCES booking_fulfilment_import_batches(id));
CREATE TRIGGER fulfilment_import_validate BEFORE INSERT ON booking_fulfilment_import_batches BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 100 THEN RAISE(ABORT,'invalid batch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.id') IS NOT 'text' OR length(json_extract(r.value,'$.id')) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.sourceRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.sourceRef'))) NOT BETWEEN 1 AND 128 OR json_extract(r.value,'$.sourceRef') IS NOT trim(json_extract(r.value,'$.sourceRef')) OR json_type(r.value,'$.bookingRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.bookingRef'))) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.amountMinor') IS NOT 'text' OR json_extract(r.value,'$.amountMinor') GLOB '*[^0-9]*' OR length(json_extract(r.value,'$.amountMinor')) NOT BETWEEN 1 AND 16 OR CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR CAST(CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) AS TEXT) IS NOT json_extract(r.value,'$.amountMinor') OR json_type(r.value,'$.fulfilmentDate') IS NOT 'text' OR date(json_extract(r.value,'$.fulfilmentDate'),'+0 days') IS NOT json_extract(r.value,'$.fulfilmentDate')) THEN RAISE(ABORT,'invalid fulfilment') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r GROUP BY json_extract(r.value,'$.sourceRef') HAVING count(*)>1) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r JOIN booking_fulfilment_import_refs x ON x.source_ref=json_extract(r.value,'$.sourceRef')) THEN RAISE(ABORT,'source reference conflict') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM credit_bookings b JOIN members m ON m.id=b.member_id WHERE b.id=json_extract(r.value,'$.bookingId') AND (json_extract(r.value,'$.bookingRef')='id:'||b.id OR (substr(json_extract(r.value,'$.bookingRef'),1,3)<>'id:' AND EXISTS(SELECT 1 FROM booking_import_refs x WHERE x.booking_id=b.id AND x.source_ref=json_extract(r.value,'$.bookingRef')))) AND m.id=json_extract(r.value,'$.memberId') AND m.member_number=json_extract(r.value,'$.memberNumber') AND m.full_name=json_extract(r.value,'$.memberName') AND m.status='active' AND b.currency=json_extract(r.value,'$.currency') AND CAST(b.requested_minor AS TEXT)=json_extract(r.value,'$.requestedMinor') AND b.requested_date=json_extract(r.value,'$.requestedDate') AND b.status=json_extract(r.value,'$.status') AND json_extract(r.value,'$.fulfilmentDate')>=b.requested_date AND CAST(COALESCE((SELECT sum(f.amount_minor) FROM credit_booking_fulfilments f WHERE f.booking_id=b.id AND NOT EXISTS(SELECT 1 FROM booking_fulfilment_voids v WHERE v.fulfilment_id=f.id)),0) AS TEXT)=json_extract(r.value,'$.recordedMinor'))) THEN RAISE(ABORT,'booking or fulfilments changed; review again') END;
END;
-- Reference rows are materialized first within the batch statement, and validated against its reviewed rows.
CREATE TRIGGER fulfilment_import_ref_validate BEFORE INSERT ON booking_fulfilment_import_refs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM booking_fulfilment_import_batches b JOIN json_each(b.rows_json) r WHERE b.id=NEW.batch_id AND json_extract(r.value,'$.id')=NEW.fulfilment_id AND json_extract(r.value,'$.sourceRef')=NEW.source_ref) THEN RAISE(ABORT,'invalid import reference') END;
END;
DROP TRIGGER fulfilment_check_insert;
CREATE TRIGGER fulfilment_check_insert BEFORE INSERT ON credit_booking_fulfilments BEGIN
 SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM credit_bookings WHERE id=NEW.booking_id AND status IN ('waiting','held')) AND NOT EXISTS(SELECT 1 FROM booking_fulfilment_import_refs x JOIN booking_fulfilment_import_batches b ON b.id=x.batch_id JOIN json_each(b.rows_json) r WHERE x.fulfilment_id=NEW.id AND json_extract(r.value,'$.id')=NEW.id AND json_extract(r.value,'$.bookingId')=NEW.booking_id AND CAST(json_extract(r.value,'$.amountMinor') AS INTEGER)=NEW.amount_minor AND json_extract(r.value,'$.fulfilmentDate')=NEW.fulfilment_date AND b.created_by=NEW.created_by) THEN RAISE(ABORT,'booking is not open') END;
 SELECT CASE WHEN NEW.amount_minor > (SELECT requested_minor - COALESCE((SELECT sum(f.amount_minor) FROM credit_booking_fulfilments f WHERE f.booking_id=NEW.booking_id AND NOT EXISTS (SELECT 1 FROM booking_fulfilment_voids v WHERE v.fulfilment_id=f.id)),0) FROM credit_bookings WHERE id=NEW.booking_id) THEN RAISE(ABORT,'fulfilment exceeds requested amount') END;
END;
CREATE TRIGGER fulfilment_import_apply AFTER INSERT ON booking_fulfilment_import_batches BEGIN
 INSERT INTO booking_fulfilment_import_refs(source_ref,fulfilment_id,batch_id) SELECT json_extract(r.value,'$.sourceRef'),json_extract(r.value,'$.id'),NEW.id FROM json_each(NEW.rows_json) r;
 INSERT INTO credit_booking_fulfilments(id,booking_id,amount_minor,fulfilment_date,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.bookingId'),CAST(json_extract(r.value,'$.amountMinor') AS INTEGER),json_extract(r.value,'$.fulfilmentDate'),NEW.created_by FROM json_each(NEW.rows_json) r;
END;
CREATE TRIGGER fulfilment_import_batch_no_update BEFORE UPDATE ON booking_fulfilment_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER fulfilment_import_batch_no_delete BEFORE DELETE ON booking_fulfilment_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER fulfilment_import_ref_no_update BEFORE UPDATE ON booking_fulfilment_import_refs BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER fulfilment_import_ref_no_delete BEFORE DELETE ON booking_fulfilment_import_refs BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
